using System;
using System.IO;
using System.Diagnostics;
using System.Security.Principal;
using System.Windows.Forms;

namespace VenkatWindowsTweaker
{
    static class Program
    {
        private static bool IsAdministrator()
        {
            try
            {
                WindowsIdentity identity = WindowsIdentity.GetCurrent();
                WindowsPrincipal principal = new WindowsPrincipal(identity);
                return principal.IsInRole(WindowsBuiltInRole.Administrator);
            }
            catch
            {
                return false;
            }
        }

        private static readonly string ScriptBase64 = "";

        [STAThread]
        static void Main()
        {
            if (!IsAdministrator())
            {
                ProcessStartInfo psiAdmin = new ProcessStartInfo();
                psiAdmin.UseShellExecute = true;
                psiAdmin.WorkingDirectory = Environment.CurrentDirectory;
                psiAdmin.FileName = Application.ExecutablePath;
                psiAdmin.Verb = "runas";
                try
                {
                    Process.Start(psiAdmin);
                }
                catch
                {
                    MessageBox.Show("Administrator privileges are required to run Venkat Windows Tweaker Suite.", "Permission Required", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                }
                return;
            }

            string tempPath = Path.Combine(Path.GetTempPath(), "Venkat_WindowsTweaker.ps1");
            try
            {
                byte[] scriptBytes = Convert.FromBase64String(ScriptBase64);
                File.WriteAllBytes(tempPath, scriptBytes);
            }
            catch (Exception ex)
            {
                MessageBox.Show("Error preparing Venkat Windows Tweaker script:\n" + ex.Message, "Launch Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                return;
            }

            ProcessStartInfo psi = new ProcessStartInfo();
            psi.FileName = "powershell.exe";
            psi.Arguments = "-NoProfile -STA -ExecutionPolicy Bypass -WindowStyle Hidden -File \"" + tempPath + "\"";
            psi.UseShellExecute = false;
            psi.CreateNoWindow = true;
            psi.WorkingDirectory = Path.GetDirectoryName(tempPath);
            try
            {
                Process.Start(psi);
            }
            catch (Exception ex)
            {
                MessageBox.Show("Error launching Venkat Windows Tweaker:\n" + ex.Message, "Launch Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }
    }
}
